            return global.ERR(.CRYPTO_OPERATION_FAILED, "Argon2 derivation failed", .{}).throw();
        }
        const alloc_res = (blk_catch_2: { break :blk_catch_2 ((jsc.ArrayBuffer.alloc(global, .ArrayBuffer, ctx.tag_length)) catch |__ce_2| { _ = &__ce_2; return global.ERR(.CRYPTO_OPERATION_FAILED, "Argon2 derivation failed", .{}).throw(); }); });
